package org.firstinspires.ftc.teamcode.biobuzz;

/** Generated by simulator/scripts/record-distances.mjs. Distances are inches, not time or motor power.
 * Measured dry-run path lengths; Blue uses the same 180-degree mirrored geometry.
 */
public final class RecordedDistances {
    private static final String[] FULL={
        "MOVING → Hive|1|0.000000",
        "MOVING → Garden|1|134.221238",
        "INTAKE:GARDEN|1|1.798537",
        "MOVING → Hive scripted far face|1|20.026776",
        "MOVING → Flower|1|6.434884",
        "INTAKE:FLOWER|1|7.576607",
        "MOVING → Hive scripted far face|2|5.809946",
        "MOVING → Flower leftover pollen|1|4.326740",
        "EXTRA_PICKUP|1|7.880768",
        "PARK|1|57.521601"
    };
    private static final String[] SINGLE={
        "MOVING → Hive|1|0.000000",
        "MOVING → Nearest Flower|1|29.595140",
        "INTAKE:NEAR_FLOWER|1|7.375013",
        "PARK|1|34.502497"
    };
    public static double inches(AutoStateMachine.Routine routine,String key,int occurrence){
        for(String row:routine==AutoStateMachine.Routine.SINGLE_TILT?SINGLE:FULL){
            String[] v=row.split("[|]");
            if(v[0].equals(key)&&Integer.parseInt(v[1])==occurrence)return Double.parseDouble(v[2]);
        }
        return Double.NaN;
    }
    private RecordedDistances(){}
}
